/**
 * flashcard-gate.mjs — the flashcard write-gate scan, payload side (STORY-058-12).
 *
 * An exact port of the report scan in the host dispatch hook
 * (`.claude/hooks/pending-task-sentinel.sh`, generated byte-identical to
 * `.codex/hooks/pending-task-sentinel.sh`): its report glob, its
 * `flashcards_flagged` parser (YAML list, `## flashcards_flagged` markdown list, JSON array
 * inline or multi-line, fenced or not), its `.processed-<hash>` marker check, and its
 * fail-closed rule for an unterminated JSON array. `dispatch_serial.mjs next` uses it to
 * refuse the next story while any card is unprocessed (cleargate-enforcement.md §4.3, §17).
 *
 * This is the one sanctioned duplicate of that logic: scaffold scripts cannot import the
 * hook, so a parity test runs the real hook and this module over the same fixtures and fails
 * on any divergence. Porting rules that keep the two identical:
 *   - bash ERE `.` and `[[:space:]]` both match `\r`, JS `.` does not — so `.` is ported as
 *     `[\s\S]` and `[[:space:]]` as `[ \t\n\v\f\r]`. A CRLF list card keeps its `\r` (and so
 *     its hash) exactly as the hook sees it.
 *   - `read -r line || [[ -n "${line}" ]]` splits on `\n` only and reads a final line that
 *     has no trailing newline.
 *   - per-line check order: JSON mode, inline `[]`, JSON open, YAML key, markdown heading,
 *     in-block stop rules, list item. A block end resets state; the file scan continues.
 *   - `[[ -f marker ]]` — a marker counts only when it is a regular file (symlinks followed).
 *
 * The scan reads no environment variable — neither the wave path's gate-bypass key nor
 * `CLEARGATE_ADVISORY`: the host dispatch hook keeps honouring the advisory break-glass per
 * dispatch; this scan has no bypass.
 */

import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

// bash: [[ "${line}" =~ ^[[:space:]]*flashcards_flagged:[[:space:]]*\[[[:space:]]*\] ]]
const INLINE_EMPTY_RE = /^[ \t\n\v\f\r]*flashcards_flagged:[ \t\n\v\f\r]*\[[ \t\n\v\f\r]*\]/;
// bash: [[ "${line}" =~ ^[[:space:]]*flashcards_flagged:[[:space:]]*\[(.*)$ ]]
const JSON_OPEN_RE = /^[ \t\n\v\f\r]*flashcards_flagged:[ \t\n\v\f\r]*\[([\s\S]*)$/;
// bash: [[ "${line}" =~ ^flashcards_flagged:[[:space:]]*$ ]]
const YAML_KEY_RE = /^flashcards_flagged:[ \t\n\v\f\r]*$/;
// bash: [[ "${line}" =~ ^##[[:space:]]+[Ff]lashcards_flagged ]]
const MD_HEADING_RE = /^##[ \t\n\v\f\r]+[Ff]lashcards_flagged/;
// bash: [[ "${line}" =~ ^[a-zA-Z_] ]]  (next top-level YAML key)
const YAML_STOP_RE = /^[a-zA-Z_]/;
// bash: [[ "${line}" =~ ^# ]]  (next markdown heading, any level)
const MD_STOP_RE = /^#/;
// bash: [[ "${line}" =~ ^[[:space:]]*-[[:space:]]+(.*) ]]
const LIST_ITEM_RE = /^[ \t\n\v\f\r]*-[ \t\n\v\f\r]+([\s\S]*)/;
// bash: JSON_STR_RE='"(([^"\\]|\\.)*)"'  (inside a bracket expression `\` is literal)
const JSON_STR_RE = /"((?:[^"\\]|\\[\s\S])*)"/;

/**
 * The card hash the hook uses for its `.processed-<hash>` marker:
 * `printf '%s' "${card}" | shasum -a 1 | cut -c1-12`.
 *
 * @param {string} card
 * @returns {string}  the first 12 hex characters of the SHA-1 of the UTF-8 card
 */
export function cardHash(card) {
  return crypto.createHash('sha1').update(String(card), 'utf8').digest('hex').slice(0, 12);
}

/**
 * Parse every `flashcards_flagged` block in one report's text, exactly as the hook does.
 *
 * @param {string} reportText
 * @returns {{ cards: string[], unterminated: boolean }}  cards in file order (empty cards
 *   skipped, never deduplicated); `unterminated` is true when the text ends inside an open
 *   JSON array — the hook's fail-closed "unparseable" case.
 */
export function flaggedCards(reportText) {
  const cards = [];
  const addCard = (card) => {
    if (card !== '') cards.push(card);
  };

  let inBlock = false;
  let blockType = ''; // 'yaml' | 'md' | 'json'

  // bash scan_json: extract every JSON string literal (unescaping \" then \\), and end the
  // block when the unquoted remainder of the line holds "]".
  const scanJson = (text) => {
    let rest = text;
    let unquoted = '';
    let m;
    while ((m = JSON_STR_RE.exec(rest)) !== null) {
      unquoted += rest.slice(0, m.index);
      rest = rest.slice(m.index + m[0].length);
      addCard(m[1].split('\\"').join('"').split('\\\\').join('\\'));
    }
    unquoted += rest;
    if (unquoted.includes(']')) {
      inBlock = false;
      blockType = '';
    }
  };

  const lines = String(reportText).split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();

  for (const line of lines) {
    if (blockType === 'json') {
      scanJson(line);
      continue;
    }
    if (INLINE_EMPTY_RE.test(line)) {
      inBlock = false;
      blockType = '';
      continue;
    }
    const open = JSON_OPEN_RE.exec(line);
    if (open) {
      inBlock = true;
      blockType = 'json';
      scanJson(open[1]);
      continue;
    }
    if (YAML_KEY_RE.test(line)) {
      inBlock = true;
      blockType = 'yaml';
      continue;
    }
    if (MD_HEADING_RE.test(line)) {
      inBlock = true;
      blockType = 'md';
      continue;
    }
    if (inBlock) {
      if (blockType === 'yaml' && YAML_STOP_RE.test(line)) {
        inBlock = false;
        blockType = '';
        continue;
      }
      if (blockType === 'md' && MD_STOP_RE.test(line)) {
        inBlock = false;
        blockType = '';
        continue;
      }
      const item = LIST_ITEM_RE.exec(line);
      if (item) {
        // List-form cards are never unescaped; strip one leading/trailing " then one '.
        let card = item[1];
        if (card.startsWith('"')) card = card.slice(1);
        if (card.endsWith('"')) card = card.slice(0, -1);
        if (card.startsWith("'")) card = card.slice(1);
        if (card.endsWith("'")) card = card.slice(0, -1);
        addCard(card);
      }
    }
  }

  return { cards, unterminated: blockType === 'json' };
}

/** A path that exists and is a regular file after following symlinks (bash `[[ -f ]]`). */
function isRegularFile(p) {
  try {
    return fs.statSync(p).isFile();
  } catch {
    return false;
  }
}

/**
 * The reports the hook scans: `<sprintDir>/*-dev.md`, `<sprintDir>/*-qa.md`,
 * `<sprintDir>/reports/*-dev.md` and `<sprintDir>/reports/*-qa.md` — one level each,
 * regular files only, dot-files excluded (bash `*` does not match a leading dot).
 *
 * @param {string} sprintDir
 * @returns {string[]}  absolute-or-as-given paths, sprintDir level first, each level sorted
 */
export function reportFiles(sprintDir) {
  const out = [];
  for (const dir of [sprintDir, path.join(sprintDir, 'reports')]) {
    let names;
    try {
      names = fs.readdirSync(dir);
    } catch {
      continue;
    }
    for (const name of names.sort()) {
      if (name.startsWith('.')) continue;
      if (!name.endsWith('-dev.md') && !name.endsWith('-qa.md')) continue;
      const full = path.join(dir, name);
      if (isRegularFile(full)) out.push(full);
    }
  }
  return out;
}

/**
 * The flashcard write-gate over one sprint directory.
 *
 * @param {{ sprintDir: string }} args
 * @returns {{ ok: boolean, unprocessed: Array<{ card: string, hash: string, report: string }>, unparseable: string[] }}
 *   `unprocessed` holds every card without a `<sprintDir>/.processed-<hash>` regular file,
 *   deduplicated by hash (first report wins); `unparseable` lists every report that ends
 *   inside an unterminated JSON array. `ok` is true iff both are empty.
 */
export function pendingFlashcards({ sprintDir }) {
  const unprocessed = [];
  const unparseable = [];
  const seen = new Set();
  for (const report of reportFiles(sprintDir)) {
    let text;
    try {
      text = fs.readFileSync(report, 'utf8');
    } catch {
      continue;
    }
    const { cards, unterminated } = flaggedCards(text);
    for (const card of cards) {
      const hash = cardHash(card);
      if (seen.has(hash)) continue;
      seen.add(hash);
      if (isRegularFile(path.join(sprintDir, `.processed-${hash}`))) continue;
      unprocessed.push({ card, hash, report });
    }
    if (unterminated) unparseable.push(report);
  }
  return { ok: unprocessed.length === 0 && unparseable.length === 0, unprocessed, unparseable };
}
